//////////////////////////////////////////////////////////////////////////////
//
// Terminal layer
//
// Hold the right C2R6 thumb (position 75). The LEFT hand sends herdr actions
// (ctrl+b prefix, then the action key); the RIGHT hand sends the terminal
// emulator chords that WezTerm and kitty share. Tapping the thumb is still a
// one-shot Right Shift, and releasing returns straight to the base layer.
//
// The chords are defined by terminal-config's
// docs/glove80-terminal-layer-chords.md -- change a chord there first.
//
// Position 75 was free: it held `&stumb LAYER_World RSFT` in stock Engrammer
// and became a plain `&kp RSHFT` when the World layer was removed.
//
//////////////////////////////////////////////////////////////////////////////

//
// The ten right-hand positions the emulator chords occupy: Y U I O P on the E
// row and H J K L SEMI on the home row. Only these are added to the trigger's
// hold-trigger-key-positions. Other right-hand keys force the Shift tap only
// when released before the 200 ms timer. A standalone hold, or a same-hand key
// held across that timer, activates Terminal; its &none keys swallow presses.
// A repeat press within 300 ms of the previous press forces the tap action.
// For ordinary held Shift use the dedicated left C6R5 key (position 46).
// README's Terminal section lists expected gestures and hardware hand tests.
//
#define TERM_RIGHT_HAND_KEYS 28 29 30 31 32 40 41 42 43 44

/ {
  behaviors {
    //
    // Positional hold-tap. `hold-trigger-key-positions` lists the left hand
    // plus the ten emulator keys and nothing else, so the trigger finger stays
    // out of the rest of its own keywell; `hold-trigger-on-release` defers the
    // decision so home-row mods still resolve first.
    //
    term_right_trigger: term_right_cross_hand_layer_shift {
      compatible = "zmk,behavior-hold-tap";
      flavor = THUMB_HOLDING_TYPE;
      hold-trigger-key-positions = <LEFT_HAND_KEYS TERM_RIGHT_HAND_KEYS>;
      hold-trigger-on-release;
      tapping-term-ms = <THUMB_HOLDING_TIME>;
      quick-tap-ms = <THUMB_REPEAT_DECAY>; // enable repeat
      #binding-cells = <2>;
      bindings = <&mo>, <&sticky_key_oneshot>;
    };
  };

